___CSS_LOADER_EXPORT___.push([module.id, `* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body {
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: #0a0a0f;
}

.grid {
    display: grid;
    grid-template-rows: auto 1fr;
    width: 100vw;
    height: 100vh;
}

.item1 {
    padding: 12px 20px;
    color: white;
    background: #111;
}

.item1 h1 {
    font-size: 1.2rem;
    font-family: sans-serif;
}

.item2 {
    position: relative; /* needed for hint overlay */
}

.drop-hint {
    position: absolute;
    bottom: 16px;
    left: 50%;
    transform: translateX(-50%);
    color: rgba(255,255,255,0.3);
    font-family: sans-serif;
    font-size: 0.85rem;
    pointer-events: none; /* don't block canvas events */
}
.item3 {
    display: flex;
    gap: 8px;
    padding: 10px 16px;
    background: #111;
    align-items: center;
}

button {
    padding: 6px 14px;
    background: #2a2a3a;
    color: #fff;
    border: 1px solid #444;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

button:hover {
    background: #3a3a5a;
    border-color: #66f;
}

button:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

#canvas-webgpu.drag-over {
    outline: 3px dashed #4af;
    outline-offset: -3px;
    opacity: 0.85;
}

.drop-hint {
    position: absolute;
    bottom: 16px;
    left: 50%;
    transform: translateX(-50%);
    color: rgba(255,255,255,0.3);
    font-family: sans-serif;
    font-size: 0.85rem;
    pointer-events: none;
